"""Minimal but complete FastTracker II XM writer (no envelopes used)."""
import struct
import numpy as np

EFF = {c: i for i, c in enumerate("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ")}

NOTE_NAMES = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}


def note_num(name):
    """'C-4' / 'C#4' / 'Db4' -> XM note 1..96 ; 'off' -> 97"""
    if isinstance(name, int):
        return name
    if name in ("off", "==="):
        return 97
    letter = name[0].upper()
    acc = name[1]
    octv = int(name[2])
    n = NOTE_NAMES[letter]
    if acc == "#":
        n += 1
    elif acc == "b":
        n -= 1
    return octv * 12 + n + 1


class Sample:
    def __init__(self, data, name="", volume=64, finetune=0, relnote=0,
                 panning=128, loop=None, pingpong=False):
        # data: float array in [-1,1]
        d = np.asarray(data, dtype=np.float64)
        self.pcm = np.clip(np.round(d * 32767.0), -32768, 32767).astype(np.int16)
        self.name = name
        self.volume = volume
        self.finetune = finetune
        self.relnote = relnote
        self.panning = panning
        self.loop = loop  # (start, length) in sample frames or None
        self.pingpong = pingpong

    def header(self):
        n = len(self.pcm)
        if self.loop:
            ls, ll = self.loop
            ltype = 2 if self.pingpong else 1
        else:
            ls, ll, ltype = 0, 0, 0
        typ = ltype | 0x10  # 16 bit
        name = self.name.encode("latin-1")[:22].ljust(22, b"\0")
        return struct.pack("<IIIBbBBbB", n * 2, ls * 2, ll * 2, self.volume,
                           self.finetune, typ, self.panning, self.relnote, 0) + name

    def body(self):
        d = self.pcm.astype(np.int32)
        delta = np.diff(np.concatenate([[0], d]))
        delta = ((delta + 32768) % 65536 - 32768).astype(np.int16)
        return delta.astype("<i2").tobytes()


class Instrument:
    def __init__(self, name, sample):
        self.name = name
        self.samples = [sample]

    def bytes(self):
        name = self.name.encode("latin-1")[:22].ljust(22, b"\0")
        out = struct.pack("<I", 263) + name + struct.pack("<BH", 0, len(self.samples))
        out += struct.pack("<I", 40)
        out += bytes(96)            # keymap: all -> sample 0
        out += bytes(48) + bytes(48)  # envelopes (unused)
        out += bytes([0, 0])        # num vol / pan points
        out += bytes([0, 0, 0, 0, 0, 0])
        out += bytes([0, 0])        # vol type, pan type (off)
        out += bytes([0, 0, 0, 0])  # autovibrato
        out += struct.pack("<H", 0)  # fadeout
        out += bytes(22)
        assert len(out) == 263
        for s in self.samples:
            out += s.header()
        for s in self.samples:
            out += s.body()
        return out


class Pattern:
    def __init__(self, rows, channels):
        self.rows = rows
        self.channels = channels
        # cell: [note, ins, vol, eff, param]
        self.cells = [[[0, 0, 0, 0, 0] for _ in range(channels)] for _ in range(rows)]

    def set(self, row, ch, note=None, ins=None, vol=None, eff=None, param=None):
        c = self.cells[row][ch]
        if note is not None:
            c[0] = note_num(note)
        if ins is not None:
            c[1] = ins
        if vol is not None:
            c[2] = vol
        if eff is not None:
            c[3] = EFF[eff] if isinstance(eff, str) else eff
        if param is not None:
            c[4] = param

    def get(self, row, ch):
        return self.cells[row][ch]

    def bytes(self):
        data = bytearray()
        for r in range(self.rows):
            for ch in range(self.channels):
                n, i, v, e, p = self.cells[r][ch]
                if n and i and v and (e or p):
                    data += bytes([n, i, v, e, p])
                    continue
                flag = 0x80
                if n: flag |= 1
                if i: flag |= 2
                if v: flag |= 4
                if e: flag |= 8
                if p: flag |= 16
                data.append(flag)
                if n: data.append(n)
                if i: data.append(i)
                if v: data.append(v)
                if e: data.append(e)
                if p: data.append(p)
        return struct.pack("<IBHH", 9, 0, self.rows, len(data)) + bytes(data)


class Module:
    def __init__(self, name, channels, speed=6, bpm=125):
        self.name = name
        self.channels = channels
        self.speed = speed
        self.bpm = bpm
        self.patterns = []
        self.instruments = []
        self.order = []
        self.restart = 0

    def write(self, path):
        out = bytearray()
        out += b"Extended Module: "
        out += self.name.encode("latin-1")[:20].ljust(20, b" ")
        out += b"\x1a"
        out += b"FastTracker v2.00   "
        out += struct.pack("<H", 0x0104)
        order = bytes(self.order).ljust(256, b"\0")
        out += struct.pack("<IHHHHHHHH", 276, len(self.order), self.restart, self.channels,
                           len(self.patterns), len(self.instruments), 1, self.speed, self.bpm)
        out += order
        for p in self.patterns:
            out += p.bytes()
        for ins in self.instruments:
            out += ins.bytes()
        with open(path, "wb") as f:
            f.write(out)
        return len(out)
