"""Composition: 'Serial Dreams' - an original keygen tune in A minor, 140 BPM.

Everything musical lives here: chords, melodies, arrangement.  Patterns are
written as real tracker data (notes, instruments, volume column, effects).
"""
import numpy as np
from xmwriter import Module, Pattern, Instrument
import instruments

ROWS = 64
NCH = 16
(KICK, SNARE, HAT, FX, BASS, LEAD, ECHO, HARM,
 CHIP, ARP, ARPE, PAD1, PAD2, PAD3, BELL, BELLE) = range(NCH)

PC = {'C': 0, 'D': 2, 'E': 4, 'F': 5, 'G': 7, 'A': 9, 'B': 11}


def nn(name):
    """'C6', 'G#5', 'Bb4', 'A-3' -> XM note number (C-0 = 1)."""
    name = name.replace('-', '')
    p = PC[name[0].upper()]
    rest = name[1:]
    if rest[0] == '#':
        p += 1; rest = rest[1:]
    elif rest[0] == 'b':
        p -= 1; rest = rest[1:]
    return int(rest) * 12 + p + 1


CHORD_PCS = {'Am': [9, 0, 4], 'F': [5, 9, 0], 'C': [0, 4, 7], 'G': [7, 11, 2],
             'Dm': [2, 5, 9], 'E': [4, 8, 11], 'Em': [4, 7, 11]}
MINOR = {'Am', 'Dm', 'Em'}
PAD_VOICING = {'Am': ['A3', 'C4', 'E4'], 'F': ['A3', 'C4', 'F4'], 'C': ['G3', 'C4', 'E4'],
               'G': ['G3', 'B3', 'D4'], 'Dm': ['A3', 'D4', 'F4'], 'E': ['G#3', 'B3', 'E4'],
               'Em': ['G3', 'B3', 'E4']}
BASS_ROOT = {'Am': 'A1', 'F': 'F1', 'C': 'C2', 'G': 'G1', 'Dm': 'D2', 'E': 'E2', 'Em': 'E2'}
ARP_ROOT = {'Am': 'A3', 'F': 'F3', 'C': 'C4', 'G': 'G3', 'Dm': 'D4', 'E': 'E3', 'Em': 'E3'}
SCALE = [9, 11, 0, 2, 4, 5, 7]  # A natural minor

PROG_A1 = ['Am', 'F', 'C', 'G']
PROG_A2 = ['Am', 'F', 'Dm', 'E']
PROG_B1 = ['F', 'G', 'Em', 'Am']
PROG_B2 = ['Dm', 'G', 'C', 'E']


def phrase(s):
    return [(int(r), n, int(d)) for r, n, d in (t.split(':') for t in s.split())]


THEME_A = [
    phrase("0:C6:2 2:B5:2 4:A5:3 7:E5:3 10:A5:2 12:B5:4"),     # Am
    phrase("0:C6:6 6:A5:2 8:F5:2 10:A5:2 12:G5:4"),            # F
    phrase("0:G5:2 2:A5:2 4:G5:3 7:E5:3 10:G5:2 12:C6:4"),     # C
    phrase("0:B5:6 6:A5:2 8:G5:2 10:D5:2 12:G5:4"),            # G
    phrase("0:C6:2 2:B5:2 4:A5:3 7:E5:3 10:A5:2 12:B5:4"),     # Am
    phrase("0:C6:6 6:D6:2 8:C6:2 10:A5:2 12:F5:4"),            # F
    phrase("0:D6:2 2:C6:2 4:A5:3 7:F5:3 10:A5:2 12:D6:4"),     # Dm
    phrase("0:B5:6 6:G#5:2 8:E5:2 10:G#5:2 12:B5:4"),          # E
]
THEME_B = [
    phrase("0:A5:3 3:C6:3 6:A5:2 8:G5:4 12:F5:2 14:G5:2"),     # F
    phrase("0:B5:3 3:D6:3 6:B5:2 8:A5:4 12:G5:2 14:A5:2"),     # G
    phrase("0:G5:3 3:B5:3 6:G5:2 8:E5:4 12:D5:2 14:E5:2"),     # Em
    phrase("0:E5:8 8:A5:2 10:B5:2 12:C6:2 14:D6:2"),           # Am
    phrase("0:D6:6 6:C6:2 8:A5:4 12:F5:2 14:A5:2"),            # Dm
    phrase("0:B5:6 6:A5:2 8:G5:4 12:D5:2 14:G5:2"),            # G
    phrase("0:E6:6 6:D6:2 8:C6:4 12:G5:2 14:C6:2"),            # C
    phrase("0:B5:8 8:G#5:4 12:E5:4"),                          # E
]
BREAK_BELL = [
    phrase("0:E6:6 6:D6:2 8:C6:4 12:B5:4"),                    # Am
    phrase("0:C6:6 6:A5:2 8:F5:8"),                            # F
    phrase("0:G5:6 6:A5:2 8:C6:4 12:E6:4"),                    # C
    phrase("0:D6:12 12:B5:4"),                                 # G
    phrase("0:E6:6 6:D6:2 8:C6:4 12:B5:4"),                    # Am
    phrase("0:C6:6 6:D6:2 8:F6:8"),                            # F
    phrase("0:F6:6 6:E6:2 8:D6:8"),                            # Dm
    [],                                                        # E (build)
]


class Song:
    def __init__(self):
        self.lib = instruments.build()
        self.ins = {name: i + 1 for i, (name, s) in enumerate(self.lib)}
        self.patterns = []

    def new(self):
        p = Pattern(ROWS, NCH)
        self.patterns.append(p)
        return p


def put(p, row, ch, note=None, ins=None, vol=None, eff=None, par=None, volcmd=None):
    if row < 0 or row >= p.rows:
        return
    c = p.cells[row][ch]
    if note is not None:
        c[0] = note if isinstance(note, int) else (97 if note == 'off' else nn(note))
    if ins is not None:
        c[1] = ins
    if vol is not None:
        c[2] = 0x10 + max(0, min(64, int(round(vol))))
    if volcmd is not None:
        c[2] = volcmd
    if eff is not None:
        c[3] = eff
        c[4] = par if par is not None else 0


# ------------------------------------------------------------------ parts
def drums_groove(S, p, bars=range(4), kick=True, snare=True, hats='full', fill=None, ghost=True):
    K, SN, HC, HO = S.ins['kick'], S.ins['snare'], S.ins['hat closed'], S.ins['hat open']
    for b in bars:
        for r in range(16):
            row = b * 16 + r
            if kick and r % 4 == 0:
                put(p, row, KICK, 'C4', K, 64)
            if snare and r in (4, 12):
                put(p, row, SNARE, 'C4', SN, 50)
            if ghost and snare and r in (7, 15) and b % 2 == 1:
                put(p, row, SNARE, 'C4', SN, 12)
            if hats == 'full':
                if r % 4 == 2:
                    put(p, row, HAT, 'C4', HO, 30)
                elif r % 4 == 0:
                    put(p, row, HAT, 'C4', HC, 26)
                else:
                    put(p, row, HAT, 'C4', HC, 16 if r % 2 else 20)
            elif hats == 'eighths':
                if r % 4 == 2:
                    put(p, row, HAT, 'C4', HC, 28)
                elif r % 4 == 0:
                    put(p, row, HAT, 'C4', HC, 16)
            elif hats == 'offbeat':
                if r % 4 == 2:
                    put(p, row, HAT, 'C4', HO, 24)
    if fill == 'short':      # last beat snare pickup
        for r, v in [(56, 30), (58, 34), (60, 40), (61, 30), (62, 46), (63, 54)]:
            put(p, r, SNARE, 'C4', SN, v)
    elif fill == 'long':     # last bar 8ths -> 16ths crescendo
        for r, v in [(48, 28), (50, 32), (52, 36), (54, 40), (56, 42), (57, 36), (58, 46),
                     (59, 40), (60, 50), (61, 46), (62, 56), (63, 62)]:
            put(p, r, SNARE, 'C4', SN, v)
    elif fill == 'roll':     # build: 2 bars of accelerating snare
        for r in range(32, 48, 2):
            put(p, r, SNARE, 'C4', SN, 22 + (r - 32))
        for r in range(48, 64):
            put(p, r, SNARE, 'C4', SN, 36 + (r - 48) * 1.7)


def crash(S, p, row=0, vol=44):
    put(p, row, FX, 'C4', S.ins['crash'], vol)


def riser(S, p, row=32, vol=40):
    put(p, row, FX, 'C4', S.ins['riser'], vol)


def bass_part(S, p, prog, style='gallop', vol=46):
    B = S.ins['bass']
    for b, ch in enumerate(prog):
        root = nn(BASS_ROOT[ch])
        for beat in range(4):
            row = b * 16 + beat * 4
            if style == 'gallop':
                put(p, row, BASS, root, B, vol)
                put(p, row + 2, BASS, root + 12, B, vol * 0.8)
                put(p, row + 3, BASS, root, B, vol * 0.9)
            elif style == 'octave':
                put(p, row, BASS, root, B, vol)
                put(p, row + 2, BASS, root + 12, B, vol * 0.85)
            elif style == 'offbeat':
                put(p, row + 2, BASS, root, B, vol)
                put(p, row + 3, BASS, root + 12, B, vol * 0.7)
            elif style == 'long' and beat == 0:
                put(p, row, BASS, root, B, vol)
            elif style == 'pulse':
                put(p, row, BASS, root, B, vol)
                put(p, row + 2, BASS, root, B, vol * 0.7)


def pad_part(S, p, prog, vol=18, pump=True, fade_in=False):
    names = ['pad L', 'pad C', 'pad R']
    for b, ch in enumerate(prog):
        for v, (chan, note) in enumerate(zip((PAD1, PAD2, PAD3), PAD_VOICING[ch])):
            row = b * 16
            if fade_in and b == 0:
                put(p, row, chan, note, S.ins[names[v]], 4)
                for r in range(1, 16):
                    put(p, row + r, chan, vol=4 + (vol - 4) * r / 15)
                continue
            put(p, row, chan, note, S.ins[names[v]], vol * (0.45 if pump else 1.0))
            if pump:
                for r in range(1, 16):
                    k = r % 4
                    put(p, row + r, chan, vol=vol * [0.45, 0.75, 0.92, 1.0][k])


def chip_voicing(ch, target=nn('G4')):
    pcs = CHORD_PCS[ch]
    best = None
    for inv in range(3):
        order = pcs[inv:] + pcs[:inv]
        ints = [0]
        for q in order[1:]:
            ints.append((q - order[0]) % 12 + (12 if (q - order[0]) % 12 < ints[-1] else 0))
        for octv in range(2, 7):
            base = octv * 12 + order[0] + 1
            d = abs(base + ints[2] / 2 - target)
            if best is None or d < best[0]:
                best = (d, base, ints[1], ints[2])
    return best[1], best[2], best[3]


def chip_part(S, p, prog, vol=30, bars=None, rate=2):
    C = S.ins['chip arp']
    for b, ch in enumerate(prog):
        if bars is not None and b not in bars:
            continue
        base, x, y = chip_voicing(ch)
        par = (x << 4) | y
        for r in range(16):
            row = b * 16 + r
            if r % rate == 0:
                put(p, row, CHIP, base, C, vol * (1.0 if r % 4 == 0 else 0.8), eff=0x0, par=par)
            else:
                put(p, row, CHIP, volcmd=0x62, eff=0x0, par=par)


ARP_MINOR = [0, 7, 12, 7, 15, 7, 12, 7]
ARP_MAJOR = [0, 7, 12, 7, 16, 7, 12, 7]


def arp_part(S, p, prog, vol=30, echo_vol=13, bars=None, delay=3, octave=0):
    A, AE = S.ins['pluck'], S.ins['pluck echo']
    for b, ch in enumerate(prog):
        if bars is not None and b not in bars:
            continue
        root = nn(ARP_ROOT[ch]) + 12 * octave
        pat = ARP_MINOR if ch in MINOR else ARP_MAJOR
        for r in range(16):
            row = b * 16 + r
            note = root + pat[r % 8]
            accent = 1.0 if r % 4 == 0 else (0.85 if r % 2 == 0 else 0.72)
            put(p, row, ARP, note, A, vol * accent)
            if echo_vol:
                put(p, row + delay, ARPE, note, AE, echo_vol * accent)


def melody(S, p, bars, chan, ins, vol, prog=None, echo=None, harm=None,
           vib=0x53, delay=3, echo_ins=None, echo_vol=None, transpose=0,
           harm_ins=None, harm_vol=None):
    """bars: list of phrases (one per bar, up to 4)."""
    for b, ph in enumerate(bars):
        for (r, name, d) in ph:
            row = b * 16 + r
            note = nn(name) + transpose
            v = vol * (1.0 if r % 4 == 0 else 0.92)
            put(p, row, chan, note, ins, v)
            if d >= 4 and vib:
                for k in range(2, d):
                    put(p, row + k, chan, eff=0x4, par=vib)
            if echo is not None:
                put(p, row + delay, echo, note, echo_ins, echo_vol)
                if d >= 4 and vib:
                    for k in range(2, d):
                        put(p, row + delay + k, echo, eff=0x4, par=vib)
            if harm is not None:
                hn = harmony_note(note, prog[b])
                put(p, row, harm, hn, harm_ins, harm_vol * (1.0 if r % 4 == 0 else 0.92))
                if d >= 4 and vib:
                    for k in range(2, d):
                        put(p, row + k, harm, eff=0x4, par=vib)


def harmony_note(note, chord):
    pcs = CHORD_PCS[chord]
    for down in (3, 4, 5):
        if (note - 1 - down) % 12 in pcs:
            return note - down
    # passing tone: diatonic third below (G# on E chord)
    scale = SCALE[:] if chord != 'E' else [9, 11, 0, 2, 4, 5, 8]
    for down in (3, 4):
        if (note - 1 - down) % 12 in scale:
            return note - down
    return note - 3


# ------------------------------------------------------------------ sections
def build_song():
    S = Song()
    L, LE, H = S.ins['lead'], S.ins['lead echo'], S.ins['harmony pwm']
    BL, BLE = S.ins['bell'], S.ins['bell echo']

    # P0 intro 1: pads fade in, chip arp chords, hats enter in bar 3
    p = S.new()
    pad_part(S, p, PROG_A1, vol=20, pump=False, fade_in=True)
    chip_part(S, p, PROG_A1, vol=26)
    arp_part(S, p, PROG_A1, vol=22, echo_vol=10, bars=[2, 3])
    drums_groove(S, p, bars=[2, 3], kick=False, snare=False, hats='eighths')
    put(p, 60, SNARE, 'C4', S.ins['snare'], 20)
    put(p, 62, SNARE, 'C4', S.ins['snare'], 28)

    # P1 intro 2: kick + bass enter, riser, snare roll
    p = S.new()
    drums_groove(S, p, kick=True, snare=False, hats='full', fill='roll')
    crash(S, p, 0, 36)
    riser(S, p, 32, 44)
    bass_part(S, p, PROG_A2, 'gallop', 42)
    pad_part(S, p, PROG_A2, vol=18, pump=True)
    chip_part(S, p, PROG_A2, vol=24)
    arp_part(S, p, PROG_A2, vol=24, echo_vol=11)

    # P2 / P3 theme A
    for half, prog in ((0, PROG_A1), (1, PROG_A2)):
        p = S.new()
        drums_groove(S, p, fill='short' if half == 0 else 'long')
        if half == 0:
            crash(S, p)
        bass_part(S, p, prog, 'gallop', 46)
        pad_part(S, p, prog, vol=14, pump=True)
        arp_part(S, p, prog, vol=24, echo_vol=11)
        melody(S, p, THEME_A[half * 4:half * 4 + 4], LEAD, L, 42, prog,
               echo=ECHO, echo_ins=LE, echo_vol=18)

    # P4 / P5 theme B
    for half, prog in ((0, PROG_B1), (1, PROG_B2)):
        p = S.new()
        drums_groove(S, p, fill='short' if half == 0 else 'long')
        if half == 0:
            crash(S, p)
        bass_part(S, p, prog, 'octave', 46)
        pad_part(S, p, prog, vol=15, pump=True)
        chip_part(S, p, prog, vol=20)
        melody(S, p, THEME_B[half * 4:half * 4 + 4], LEAD, L, 42, prog,
               echo=ECHO, echo_ins=LE, echo_vol=18)

    # P6 break: pads, arps, bells, long bass
    p = S.new()
    crash(S, p, 0, 34)
    bass_part(S, p, PROG_A1, 'long', 40)
    pad_part(S, p, PROG_A1, vol=20, pump=False)
    arp_part(S, p, PROG_A1, vol=22, echo_vol=12)
    melody(S, p, BREAK_BELL[:4], BELL, BL, 44, PROG_A1, echo=BELLE,
           echo_ins=BLE, echo_vol=20, vib=0, delay=3)
    drums_groove(S, p, bars=[2, 3], kick=False, snare=False, hats='offbeat')

    # P7 build
    p = S.new()
    drums_groove(S, p, kick=True, snare=False, hats='full', fill='roll')
    riser(S, p, 32, 44)
    bass_part(S, p, PROG_A2, 'octave', 42)
    pad_part(S, p, PROG_A2, vol=18, pump=True)
    arp_part(S, p, PROG_A2, vol=24, echo_vol=12)
    chip_part(S, p, PROG_A2, vol=18, bars=[2, 3])
